INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36497, 0, 0, 'Finally, a captive audience!', 14, 0, 100, 0, 0, 16595, 'bronjham SAY_AGGRO'),
(36497, 1, 0, 'Fodder for the engine.', 14, 0, 100, 0, 0, 16596, 'bronjham SAY_SLAY_1'),
(36497, 1, 1, 'Another soul to strengthen the host!', 14, 0, 100, 0, 0, 16597, 'bronjham SAY_SLAY_2'),
(36497, 2, 0, 'The Devourer awaits...', 14, 0, 100, 0, 0, 16598, 'bronjham SAY_DEATH'),
(36497, 3, 0, 'The vortex of the harvested calls to you!', 14, 0, 100, 0, 0, 16599, 'bronjham SAY_SOUL_STORM'),
(36497, 4, 0, 'I will sever your soul from your body!', 14, 0, 100, 0, 0, 16600, 'bronjham SAY_CORRUPT_SOUL');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36502, 0, 0, 'You dare look upon the host of souls? I SHALL DEVOUR YOU WHOLE!', 14, 0, 100, 0, 0, 16884, 'devoureur SAY_FACE_ANGER_AGGRO'),
