(36502, 1, 1, 'Doomed for eternity!', 14, 0, 100, 0, 0, 16886, 'devoureur SAY_FACE_ANGER_SLAY_2'),
(36502, 2, 0, 'Damnation!', 14, 0, 100, 0, 0, 16896, 'devoureur SAY_FACE_SORROW_SLAY_1'),
(36502, 2, 1, 'Doomed for eternity!', 14, 0, 100, 0, 0, 16897, 'devoureur SAY_FACE_SORROW_SLAY_2'),
(36502, 3, 0, 'Damnation!', 14, 0, 100, 0, 0, 16891, 'devoureur SAY_FACE_DESIRE_SLAY_1'),
(36502, 3, 1, 'Doomed for eternity!', 14, 0, 100, 0, 0, 16892, 'devoureur SAY_FACE_DESIRE_SLAY_2'),
(36502, 4, 0, 'The swell of souls will not be abated! You only delay the inevitable.', 14, 0, 100, 0, 0, 16887, 'devoureur SAY_FACE_ANGER_DEATH'),
(36502, 4, 1, 'The swell of souls will not be abated! You only delay the inevitable.', 14, 0, 100, 0, 0, 16898, 'devoureur SAY_FACE_SORROW_DEATH'),
(36502, 4, 2, 'The swell of souls will not be abated! You only delay the inevitable.', 14, 0, 100, 0, 0, 16893, 'devoureur SAY_FACE_DESIRE_DEATH'),
