(36502, 6, 0, '%s begins to |cFFFF0000Unleash Souls!|r', 41, 0, 100, 0, 0, 0, 'devoureur EMOTE_UNLEASH_SOUL'),
(36502, 7, 0, 'SUFFERING! ANGUISH! CHAOS! RISE AND FEED!', 14, 0, 100, 0, 0, 16888, 'devoureur SAY_FACE_ANGER_UNLEASH_SOUL'),
(36502, 7, 1, 'SUFFERING! ANGUISH! CHAOS! RISE AND FEED!', 14, 0, 100, 0, 0, 16899, 'devoureur SAY_FACE_SORROW_UNLEASH_SOUL'),
(36502, 7, 2, 'SUFFERING! ANGUISH! CHAOS! RISE AND FEED!', 14, 0, 100, 0, 0, 16894, 'devoureur SAY_FACE_DESIRE_UNLEASH_SOUL'),
(36502, 8, 0, '%s begins to cast Wailing Souls!', 41, 0, 100, 0, 0, 0, 'devoureur EMOTE_WAILING_SOUL'),
(36502, 9, 0, 'Stare into the abyss and see your end.', 14, 0, 100, 0, 0, 16889, 'devoureur SAY_FACE_ANGER_WAILING_SOUL'),
(36502, 9, 1, 'Stare into the abyss and see your end.', 14, 0, 100, 0, 0, 16895, 'devoureur SAY_FACE_DESIRE_WAILING_SOUL'),
(36502, 10, 0, 'SUFFERING! ANGUISH! CHAOS! RISE AND FEED!', 14, 0, 100, 0, 0, 16899, 'Devoureur SAY_FACE_DESIRE_UNLEASH_SOUL'),
(36502, 11, 0, 'Stare into the abyss and see your end.', 14, 0, 100, 0, 0, 16895, 'Devoureur SAY_FACE_DESIRE_WAILING_SOUL'),
(36502, 12, 0, 'Stare into the abyss and see your end.', 14, 0, 100, 0, 0, 16895, 'Devoureur SAY_FACE_ANGER_WAILING_SOUL'),
(36502, 13, 0, '%s begins to cast Wailing Souls!', 41, 0, 100, 0, 0, 0, ''),
