INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37596, 0, 0, 'The Argent Crusade and the Knights of the Ebon Blade have assaulted the gates of the Icecrown Citadel and are preparing for a massive attack upon the Scourge. Our mission is a bit more subtle, but equally as important.', 12, 0, 100, 0, 0, 17038, 'sylvanas SAY_INTRO_1'),
(37596, 1, 0, 'With the attention of the Lich King turned towards the front gate, we\'ll be working our way through the side in search of information that will enable us to defeat him - once and for all.', 12, 0, 100, 0, 0, 17039, 'sylvanas SAY_INTRO_2'),
(37596, 2, 0, 'Our scouts have reported that the Lich King has a private chamber, outside of the Frozen Throne, deep within a place called the Halls of Reflection. That is our target, champions. ', 12, 0, 100, 0, 0, 17040, 'sylvanas SAY_INTRO_3'),
(37596, 3, 0, 'We will cut a swath of destruction through this cursed place and find a way to enter the Halls of Reflection. If there is anything of value to be found here, it will be found in the halls.', 12, 0, 100, 0, 0, 17041, 'sylvanas SAY_INTRO_4'),
(37596, 4, 0, 'Your first mission is to destroy the machines of death within this malevolent engine of souls and clear a path for our soldiers. ', 12, 0, 100, 0, 0, 17042, 'sylvanas SAY_INTRO_5'),
(37596, 5, 0, 'The Dark Lady watches over you. Make haste!', 12, 0, 100, 0, 0, 17043, 'sylvanas SAY_INTRO_6');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37597, 0, 0, 'Thank the Light for seeing you here safely! We have much work to do if we are to defeat the Lich King and put an end to the Scourge.', 12, 0, 100, 0, 0, 16617, 'jaina SAY_INTRO_1'),
(37597, 1, 0, 'Our allies within the Argent Crusade and the Knights of the Ebon Blade have broken through the front gate of Icecrown and are attempting to establish a foothold within the citadel. ', 12, 0, 100, 0, 0, 16618, 'jaina SAY_INTRO_2'),
(37597, 2, 0, 'Their success hinges upon what we discover within these cursed halls. Although our mission is fraught with peril, we must persevere!', 12, 0, 100, 0, 0, 16619, 'jaina SAY_INTRO_3'),
(37597, 3, 0, 'With the attention of the Lich King drawn towards the front gate, we will be working our way through the side in search of information that will enable us to defeat the Scourge once and for all.', 12, 0, 100, 0, 0, 16620, 'jaina SAY_INTRO_4'),
(37597, 4, 0, 'King Varian\'s SI:7 agents have gathered information about a private sanctum of the Lich King\'s deep within a place called the Halls of Reflection. ', 12, 0, 100, 0, 0, 16621, 'jaina SAY_INTRO_5'),
(37597, 5, 0, 'We will carve a path through this wretched place and find a way to enter the Halls of Reflection. I sense powerful magic hidden away within those halls. Magic that could be the key to destroying the Scourge!', 12, 0, 100, 0, 0, 16622, 'jaina SAY_INTRO_6'),
(37597, 6, 0, 'Your first mission is to destroy the machines of death within this malevolent engine of souls and clear a path for our soldiers. ', 12, 0, 100, 0, 0, 16623, 'jaina SAY_INTRO_7'),
(37597, 7, 0, 'Make haste, champions! I will prepare the troops to fall in behind you.', 12, 0, 100, 0, 0, 16624, 'jaina SAY_INTRO_8');
